#!/usr/bin/env node
/**
 * Playwright visual QA for the static research site.
 *
 *   node tests/visual_qa.js            # checks + JSON report, no screenshots
 *   node tests/visual_qa.js --shots    # also write tests/screenshots/*.png
 *
 * Requires Playwright with Chromium. On minimal Linux images the browser may
 * need extra shared libraries; see docs/REPRODUCE.md. The report is committed
 * as tests/qa-report.json and is regenerated by this script.
 */
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');

const ROOT = path.resolve(__dirname, '..');
const SITE = pathToFileURL(path.join(ROOT, 'site', 'index.html')).href;
const OUT = path.join(__dirname, 'screenshots');
const SHOTS = process.argv.includes('--shots');
const VIEWPORTS = [
  { w: 1440, h: 1000, name: 'desktop-1440' },
  { w: 1280, h: 900, name: 'desktop-1280' },
  { w: 768, h: 1024, name: 'tablet-768' },
  { w: 390, h: 844, name: 'mobile-390' },
  { w: 360, h: 800, name: 'mobile-360' },
];

(async () => {
  const browser = await chromium.launch();
  const report = { viewports: {}, console: [], pageerrors: [], requestsfailed: [], checks: {} };
  for (const vp of VIEWPORTS) {
    const page = await browser.newPage({ viewport: { width: vp.w, height: vp.h } });
    page.on('console', m => { if (m.type() === 'error') report.console.push({ vp: vp.name, text: m.text() }); });
    page.on('pageerror', e => report.pageerrors.push({ vp: vp.name, text: String(e) }));
    page.on('requestfailed', r => report.requestsfailed.push({ vp: vp.name, url: r.url() }));
    await page.goto(SITE, { waitUntil: 'load' });
    await page.waitForTimeout(200);
    const metrics = await page.evaluate(() => {
      const de = document.documentElement;
      const svgs = [...document.querySelectorAll('.figure svg')];
      return {
        scrollWidth: de.scrollWidth, clientWidth: de.clientWidth,
        figures: svgs.length,
        visibleFigures: svgs.filter(s => { const r = s.getBoundingClientRect(); return r.width > 10 && r.height > 10; }).length,
        texts: [...document.querySelectorAll('.figure svg text')].filter(t => t.getBoundingClientRect().width > 0).length,
        rows: document.querySelectorAll('#trials tbody tr').length,
      };
    });
    report.viewports[vp.name] = { ...metrics, overflow: metrics.scrollWidth > metrics.clientWidth + 1 };
    if (SHOTS) {
      fs.mkdirSync(OUT, { recursive: true });
      await page.evaluate(() => document.documentElement.setAttribute('data-theme', 'light'));
      await page.screenshot({ path: path.join(OUT, `${vp.name}-light.png`) });
      await page.evaluate(() => document.documentElement.setAttribute('data-theme', 'dark'));
      await page.waitForTimeout(100);
      await page.screenshot({ path: path.join(OUT, `${vp.name}-dark.png`) });
    }
    if (vp.name === 'desktop-1440') {
      await page.evaluate(() => document.documentElement.setAttribute('data-theme', 'light'));
      await page.click('[data-filter="task"][data-value="t2_replay_perf"]');
      const count1 = (await page.locator('#count').textContent()).trim();
      await page.click('[data-filter="agent"][data-value="jcode"]');
      const count2 = (await page.locator('#count').textContent()).trim();
      await page.click('[data-filter="task"][data-value=""]');
      await page.click('[data-filter="agent"][data-value=""]');
      const count3 = (await page.locator('#count').textContent()).trim();
      report.checks.interactions = { count1, count2, count3 };
    }
    await page.close();
  }
  await browser.close();
  report.checks.consoleErrors = report.console.length;
  report.checks.pageErrors = report.pageerrors.length;
  report.checks.failedRequests = report.requestsfailed.length;
  report.checks.noOverflow = Object.values(report.viewports).every(v => !v.overflow);
  report.checks.allFigures = Object.values(report.viewports).every(v => v.visibleFigures === 6 && v.texts > 80);
  report.checks.tableRows = Object.values(report.viewports).every(v => v.rows === 9);
  report.checks.ok = Object.entries(report.checks).filter(([k]) => k !== 'interactions').every(([, v]) => v === 0 || v === true);
  fs.writeFileSync(path.join(__dirname, 'qa-report.json'), JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify(report.checks, null, 2));
  process.exit(report.checks.ok ? 0 : 1);
})().catch(err => { console.error(err); process.exit(2); });
